import type { JobRunRow, JobRunStatus } from '@ctxlayer/shared'
import type { Env } from '../../env'
import { newId } from './util'

/**
 * Run ledger for recurring batch jobs (migration 0035). Written by
 * `ops/job-runs.ts:recordJobRun` around every cron task and git-sync run;
 * read by `GET /api/admin/jobs`. Rows are pruned after 90 days by the
 * nightly 'jobs-prune' task.
 */

export interface InsertJobRunInput {
  task: string
  startedAt: number // unix seconds
  durationMs: number
  status: JobRunStatus
  summary: Record<string, unknown> | null
  error: string | null
}

export async function insertJobRun(env: Env, input: InsertJobRunInput): Promise<void> {
  await env.DB.prepare(
    `INSERT INTO job_runs (id, task, started_at, duration_ms, status, summary, error)
     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)`
  )
    .bind(
      newId(),
      input.task,
      input.startedAt,
      input.durationMs,
      input.status,
      input.summary ? JSON.stringify(input.summary) : null,
      input.error
    )
    .run()
}

export interface ListJobRunsOpts {
  since: number // unix seconds lower bound
  task?: string
  limit: number
}

export async function listJobRuns(env: Env, opts: ListJobRunsOpts): Promise<JobRunRow[]> {
  const where = ['started_at >= ?1']
  const binds: unknown[] = [opts.since]
  if (opts.task) {
    where.push(`task = ?${binds.length + 1}`)
    binds.push(opts.task)
  }
  const res = await env.DB.prepare(
    `SELECT id, task, started_at, duration_ms, status, summary, error
     FROM job_runs
     WHERE ${where.join(' AND ')}
     ORDER BY started_at DESC
     LIMIT ?${binds.length + 1}`
  )
    .bind(...binds, opts.limit)
    .all<{
      id: string
      task: string
      started_at: number
      duration_ms: number
      status: JobRunStatus
      summary: string | null
      error: string | null
    }>()
  return (res.results ?? []).map((r) => ({
    id: r.id,
    task: r.task,
    startedAt: r.started_at,
    durationMs: r.duration_ms,
    status: r.status,
    summary: r.summary ? safeParseObject(r.summary) : null,
    error: r.error
  }))
}

/** Delete runs older than the cutoff; returns rows removed. */
export async function pruneJobRuns(env: Env, olderThanSec: number): Promise<number> {
  const cutoff = Math.floor(Date.now() / 1000) - olderThanSec
  const res = await env.DB.prepare(`DELETE FROM job_runs WHERE started_at < ?1`)
    .bind(cutoff)
    .run()
  return res.meta.changes ?? 0
}

function safeParseObject(raw: string): Record<string, unknown> | null {
  try {
    const parsed: unknown = JSON.parse(raw)
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : null
  } catch {
    return null
  }
}

import type { JobRunStatus } from '@ctxlayer/shared'
import type { Env } from '../env'
import { insertJobRun } from '../db/queries/job-runs'
import { scrubErrorForStorage } from '../usage/error-detail'
import { errMessage } from '../util/errors'

/**
 * Records one execution of a recurring batch job into the `job_runs`
 * ledger (Admin · Jobs). Wrap the job body:
 *
 *   await recordJobRun(env, 'keep-warm', async () => {
 *     const r = await keepWarmUserCredentials(env, nowSec)
 *     return { status: r.failed > 0 ? 'partial' : 'ok', summary: r }
 *   })
 *
 * Semantics:
 *   - fn's returned outcome sets status/summary (default 'ok'); a THROW
 *     records an error row (message scrubbed) and RE-THROWS, so the
 *     existing per-task catch + ops alert paths stay exactly as they are.
 *   - the ledger is observability, not control: a failed insert is logged
 *     and swallowed — it must never break or retry the job itself.
 */

export interface JobRunOutcome {
  status?: JobRunStatus
  summary?: Record<string, unknown>
  /** Failure detail for non-ok outcomes that did not throw (already scrubbed by caller or plain text). */
  error?: string
}

export async function recordJobRun<T extends JobRunOutcome | undefined | void>(
  env: Env,
  task: string,
  fn: () => Promise<T>
): Promise<T> {
  const startedAt = Math.floor(Date.now() / 1000)
  const t0 = Date.now()
  const write = async (status: JobRunStatus, summary?: Record<string, unknown>, error?: string) => {
    try {
      await insertJobRun(env, {
        task,
        startedAt,
        durationMs: Date.now() - t0,
        status,
        summary: summary ?? null,
        error: error ?? null
      })
    } catch (err) {
      console.error(`[job-runs] ${task}: ledger write failed: ${errMessage(err)}`)
    }
  }
  try {
    const out = await fn()
    const o: JobRunOutcome = out ?? {}
    await write(o.status ?? 'ok', o.summary, o.error)
    return out
  } catch (err) {
    await write('error', undefined, scrubErrorForStorage(errMessage(err)))
    throw err
  }
}

