/**
 * Admin REST for the Jobs dashboard. `GET /api/admin/jobs?range=30d&task=
 * git-sync` returns the recorded runs of recurring batch jobs (cron tasks
 * + git-sync runs) within the window, newest-first. Read-only; rows are
 * written by `ops/job-runs.ts:recordJobRun` at each job site.
 */

import { Hono } from 'hono'
import type { AdminJobsResponse } from '@ctxlayer/shared'
import type { Env } from '../env'
import { requireAdmin, type AuthedVariables } from '../auth/middleware'
import { listJobRuns } from '../db/queries/job-runs'
import { rangeCutoff } from '../db/queries/usage-read'
import { parseRange, parseOffset } from './usage'

/** Runs returned per request — the ledger is bounded, but cap the wire. */
const RUNS_LIMIT = 1000

export const adminJobsRoute = new Hono<{ Bindings: Env; Variables: AuthedVariables }>()
adminJobsRoute.use('*', requireAdmin)

adminJobsRoute.get('/', async (c) => {
  const url = new URL(c.req.url)
  const range = parseRange(url.searchParams.get('range'))
  const offsetSec = parseOffset(url.searchParams.get('tz'))
  const task = url.searchParams.get('task')?.trim() || undefined
  const body: AdminJobsResponse = {
    range,
    runs: await listJobRuns(c.env, {
      since: rangeCutoff(range, offsetSec) ?? 0,
      task,
      limit: RUNS_LIMIT
    })
  }
  return c.json(body)
})

import { useEffect, useRef, useState } from 'react'
import { Group, Text } from '@mantine/core'
import { USAGE_RANGE_DAYS, type JobRunRow, type UsageRange } from '@ctxlayer/shared'

/**
 * Per-task run timeline for Admin · Jobs: one lane per task, one mark per
 * recorded run positioned on the time axis — cadence gaps and error
 * clusters are visible at a glance, which the runs table can't show.
 *
 * Hand-rolled inline SVG like `usage/charts.tsx` (no chart lib).
 * Status is encoded by color AND shape (dataviz rule: status never rides
 * color alone — validated palette green-9/yellow-6/red-8, protan ΔE 18.7):
 * ok = filled circle, partial = diamond, error = ×. Marks carry a 2px
 * surface ring so overlapping runs stay separable; hover = native SVG
 * <title> tooltip (the app idiom); click opens the run drawer.
 */

const LANE_H = 30
const M_LEFT = 150 // task label gutter
const M_RIGHT = 84 // per-lane stat gutter
const M_TOP = 8
const M_BOTTOM = 22
const SECONDS_PER_DAY = 86400

const STATUS_COLOR: Record<JobRunRow['status'], string> = {
  ok: 'var(--mantine-color-green-9, #2b8a3e)',
  partial: 'var(--mantine-color-yellow-6, #fab005)',
  error: 'var(--mantine-color-red-8, #e03131)'
}
const SURFACE_RING = 'var(--mantine-color-body, #fff)'

export function RunTimeline({
  runs,
  range,
  onSelect
}: {
  runs: JobRunRow[]
  range: UsageRange
  onSelect: (run: JobRunRow) => void
}) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [width, setWidth] = useState(0)

  useEffect(() => {
    const el = containerRef.current
    if (!el) return
    setWidth(el.clientWidth)
    const ro = new ResizeObserver((entries) => {
      const w = entries[0]?.contentRect.width ?? 0
      if (w > 0) setWidth(w)
    })
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  return (
    <div ref={containerRef} style={{ width: '100%' }}>
      {width > 0 && <Lanes runs={runs} range={range} width={width} onSelect={onSelect} />}
      <Legend />
    </div>
  )
}

function Lanes({
  runs,
  range,
  width,
  onSelect
}: {
  runs: JobRunRow[]
  range: UsageRange
  width: number
  onSelect: (run: JobRunRow) => void
}) {
  const now = Math.floor(Date.now() / 1000)
  const rangeDays = USAGE_RANGE_DAYS[range]
  const oldest = runs.length ? Math.min(...runs.map((r) => r.startedAt)) : now - SECONDS_PER_DAY
  // 'all' has no fixed window — span from the oldest recorded run.
  const start = rangeDays ? now - rangeDays * SECONDS_PER_DAY : Math.min(oldest, now - SECONDS_PER_DAY)
  const span = Math.max(1, now - start)

  const tasks = [...new Set(runs.map((r) => r.task))].sort()
  const height = M_TOP + Math.max(1, tasks.length) * LANE_H + M_BOTTOM
  const plotW = Math.max(0, width - M_LEFT - M_RIGHT)
  const x = (ts: number) => M_LEFT + ((ts - start) / span) * plotW

  const ticks = timeTicks(start, now)

  if (runs.length === 0) {
    return (
      <Text c="dimmed" fz="sm">
        No recorded runs in this period yet — the ledger starts collecting from this deploy on.
      </Text>
    )
  }

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      style={{ display: 'block' }}
      role="img"
      aria-label="Job runs per task over time"
    >
      {/* recessive vertical time grid + tick labels */}
      {ticks.map((t) => (
        <g key={`t-${t.ts}`}>
          <line
            x1={x(t.ts)}
            x2={x(t.ts)}
            y1={M_TOP}
            y2={height - M_BOTTOM}
            stroke="var(--border, #2a2a2a)"
            strokeWidth={0.5}
            opacity={0.5}
          />
          <text
            x={x(t.ts)}
            y={height - 6}
            textAnchor="middle"
            fontSize={10}
            fill="var(--text-dim, #888)"
          >
            {t.label}
          </text>
        </g>
      ))}

      {tasks.map((task, i) => {
        const laneY = M_TOP + i * LANE_H + LANE_H / 2
        const laneRuns = runs.filter((r) => r.task === task)
        const okCount = laneRuns.filter((r) => r.status === 'ok').length
        return (
          <g key={task}>
            <line
              x1={M_LEFT}
              x2={width - M_RIGHT}
              y1={laneY}
              y2={laneY}
              stroke="var(--border, #2a2a2a)"
              strokeWidth={0.5}
              opacity={0.35}
            />
            <text
              x={M_LEFT - 10}
              y={laneY + 3.5}
              textAnchor="end"
              fontSize={11}
              fontFamily="var(--mantine-font-family-monospace, monospace)"
              fill="var(--text, #ddd)"
            >
              {task}
            </text>
            <text
              x={width - M_RIGHT + 10}
              y={laneY + 3.5}
              fontSize={10}
              fill="var(--text-dim, #888)"
            >
              {laneRuns.length} run{laneRuns.length === 1 ? '' : 's'} ·{' '}
              {Math.round((okCount / laneRuns.length) * 100)}%
            </text>
            {laneRuns.map((r) => (
              <RunMark key={r.id} run={r} cx={x(r.startedAt)} cy={laneY} onSelect={onSelect} />
            ))}
          </g>
        )
      })}
    </svg>
  )
}

function RunMark({
  run,
  cx,
  cy,
  onSelect
}: {
  run: JobRunRow
  cx: number
  cy: number
  onSelect: (run: JobRunRow) => void
}) {
  const color = STATUS_COLOR[run.status]
  const tip = [
    new Date(run.startedAt * 1000).toLocaleString(),
    `${run.task} · ${run.status} · ${run.durationMs}ms`,
    run.summary ? summaryLine(run.summary) : null,
    run.error ? `error: ${run.error.slice(0, 200)}` : null
  ]
    .filter(Boolean)
    .join('\n')

  return (
    <g
      onClick={() => onSelect(run)}
      style={{ cursor: 'pointer' }}
      role="button"
      aria-label={`${run.task} run, ${run.status}`}
    >
      <title>{tip}</title>
      {/* invisible hit target well above mark size */}
      <circle cx={cx} cy={cy} r={10} fill="transparent" />
      {run.status === 'ok' && (
        <circle cx={cx} cy={cy} r={4.5} fill={color} stroke={SURFACE_RING} strokeWidth={1.5} />
      )}
      {run.status === 'partial' && (
        <rect
          x={cx - 4.5}
          y={cy - 4.5}
          width={9}
          height={9}
          transform={`rotate(45 ${cx} ${cy})`}
          fill={color}
          stroke={SURFACE_RING}
          strokeWidth={1.5}
        />
      )}
      {run.status === 'error' && (
        <g stroke={color} strokeWidth={2.5} strokeLinecap="round">
          {/* surface ring behind the × so it reads on top of neighbours */}
          <g stroke={SURFACE_RING} strokeWidth={4.5}>
            <line x1={cx - 4.5} y1={cy - 4.5} x2={cx + 4.5} y2={cy + 4.5} />
            <line x1={cx - 4.5} y1={cy + 4.5} x2={cx + 4.5} y2={cy - 4.5} />
          </g>
          <line x1={cx - 4.5} y1={cy - 4.5} x2={cx + 4.5} y2={cy + 4.5} />
          <line x1={cx - 4.5} y1={cy + 4.5} x2={cx + 4.5} y2={cy - 4.5} />
        </g>
      )}
    </g>
  )
}

function Legend() {
  return (
    <Group gap="md" mt={6}>
      <LegendItem label="ok">
        <circle cx={7} cy={7} r={4.5} fill={STATUS_COLOR.ok} />
      </LegendItem>
      <LegendItem label="partial">
        <rect x={2.5} y={2.5} width={9} height={9} transform="rotate(45 7 7)" fill={STATUS_COLOR.partial} />
      </LegendItem>
      <LegendItem label="error">
        <g stroke={STATUS_COLOR.error} strokeWidth={2.5} strokeLinecap="round">
          <line x1={3} y1={3} x2={11} y2={11} />
          <line x1={3} y1={11} x2={11} y2={3} />
        </g>
      </LegendItem>
    </Group>
  )
}

function LegendItem({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <Group gap={5} align="center">
      <svg width={14} height={14} aria-hidden>
        {children}
      </svg>
      <Text fz="xs" c="dimmed">
        {label}
      </Text>
    </Group>
  )
}

/** ~5 evenly spaced ticks labeled with the local short date. */
function timeTicks(start: number, end: number): Array<{ ts: number; label: string }> {
  const n = 5
  const out: Array<{ ts: number; label: string }> = []
  for (let i = 0; i <= n; i++) {
    const ts = start + ((end - start) * i) / n
    out.push({
      ts,
      label: new Date(ts * 1000).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
    })
  }
  return out
}

function summaryLine(summary: Record<string, unknown>): string {
  return Object.entries(summary)
    .slice(0, 5)
    .map(([k, v]) => `${k}=${typeof v === 'object' ? JSON.stringify(v) : String(v)}`)
    .join(' · ')
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  Alert,
  Badge,
  Code,
  Drawer,
  Group,
  Select,
  Stack,
  Text,
  Title
} from '@mantine/core'
import { USAGE_RANGE_LABEL, type AdminJobsResponse, type JobRunRow, type UsageRange } from '@ctxlayer/shared'
import { Section } from '../../components/admin-bits'
import { RunTimeline } from '../../components/jobs/run-timeline'
import { Panel } from '../../components/usage/summary'
import { clickableRow } from '../../lib/a11y'
import { fetchAdminJobs } from '../../lib/api'
import { explain } from '../../lib/explain'
import { absDateTime, relativeTime } from '../../lib/time'
import { useUsageRange } from '../../lib/use-usage-range'

/**
 * Admin · Jobs — execution history of the recurring batch jobs (cron
 * tasks + per-repo git-sync runs) from the `job_runs` ledger. The
 * timeline shows cadence + status per task; the table below is the
 * drill-down, and a row click opens the full summary/error drawer.
 */

const RANGE_OPTIONS = (Object.keys(USAGE_RANGE_LABEL) as UsageRange[]).map((r) => ({
  value: r,
  label: USAGE_RANGE_LABEL[r]
}))

type Status =
  | { kind: 'loading' }
  | { kind: 'error'; message: string }
  | { kind: 'ready'; data: AdminJobsResponse }

export function AdminJobs() {
  const [range, setRange] = useUsageRange('jobs')
  const [task, setTask] = useState<string>('all')
  const [status, setStatus] = useState<Status>({ kind: 'loading' })
  const [selected, setSelected] = useState<JobRunRow | null>(null)
  const ctrlRef = useRef<AbortController | null>(null)

  const load = useCallback((r: UsageRange) => {
    ctrlRef.current?.abort()
    const ctrl = new AbortController()
    ctrlRef.current = ctrl
    setStatus({ kind: 'loading' })
    fetchAdminJobs({ range: r }, ctrl.signal).then(
      (data) => {
        if (!ctrl.signal.aborted) setStatus({ kind: 'ready', data })
      },
      (err) => {
        if (ctrl.signal.aborted) return
        setStatus({ kind: 'error', message: explain(err) })
      }
    )
  }, [])

  useEffect(() => {
    load(range)
    return () => ctrlRef.current?.abort()
  }, [range, load])

  const runs = status.kind === 'ready' ? status.data.runs : []
  const taskOptions = useMemo(() => {
    const present = [...new Set(runs.map((r) => r.task))].sort()
    return [{ value: 'all', label: 'All types' }, ...present.map((t) => ({ value: t, label: t }))]
  }, [runs])
  const filtered = useMemo(
    () => (task === 'all' ? runs : runs.filter((r) => r.task === task)),
    [runs, task]
  )

  return (
    <Stack gap="lg">
      <Group justify="space-between" align="center" wrap="nowrap">
        <Title order={2} fz={20} fw={600}>
          Admin · Jobs
        </Title>
        <Group gap="xs" wrap="nowrap">
          <Select
            size="xs"
            data={taskOptions}
            value={task}
            onChange={(v) => setTask(v ?? 'all')}
            w={170}
            allowDeselect={false}
            aria-label="Filter by job type"
          />
          <Select
            size="xs"
            data={RANGE_OPTIONS}
            value={range}
            onChange={(v) => v && setRange(v as UsageRange)}
            w={150}
            allowDeselect={false}
          />
        </Group>
      </Group>

      {status.kind === 'error' && (
        <Alert color="red" variant="light" radius="sm">
          {status.message}
        </Alert>
      )}

      {status.kind === 'loading' && <Text c="dimmed">Loading…</Text>}

      {status.kind === 'ready' && (
        <>
          <Panel
            title="Run timeline"
            subtitle="One lane per job, one mark per run. Hover a mark for its summary; click for the full detail."
          >
            <RunTimeline runs={filtered} range={range} onSelect={setSelected} />
          </Panel>

          <Panel title="Runs" subtitle="Newest first. Click a row for the full summary and error detail.">
            {filtered.length === 0 ? (
              <Text c="dimmed" fz="sm">
                No runs recorded in this period.
              </Text>
            ) : (
              <table className="data-table">
                <thead>
                  <tr>
                    <th style={{ width: 150 }}>When</th>
                    <th>Task</th>
                    <th style={{ width: 90, textAlign: 'right' }}>Duration</th>
                    <th style={{ width: 80 }}>Status</th>
                    <th>Summary</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((r) => (
                    <tr key={r.id} {...clickableRow(() => setSelected(r))}>
                      <td className="text-muted" title={absDateTime(r.startedAt)}>
                        {relativeTime(r.startedAt)}
                      </td>
                      <td>
                        <Badge
                          variant="light"
                          size="sm"
                          color="gray"
                          style={{ fontFamily: 'var(--mantine-font-family-monospace, monospace)' }}
                        >
                          {r.task}
                        </Badge>
                      </td>
                      <td className="text-muted" style={{ textAlign: 'right' }}>
                        {formatDuration(r.durationMs)}
                      </td>
                      <td>
                        <StatusBadge status={r.status} />
                      </td>
                      <td
                        className="text-muted"
                        style={{
                          maxWidth: 380,
                          fontFamily: 'var(--mantine-font-family-monospace, monospace)',
                          fontSize: 11
                        }}
                      >
                        {r.error ? truncate(r.error, 80) : summaryPreview(r.summary)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </Panel>
        </>
      )}

      {selected && <RunDrawer run={selected} onClose={() => setSelected(null)} />}
    </Stack>
  )
}

function StatusBadge({ status }: { status: JobRunRow['status'] }) {
  const color = status === 'ok' ? 'green' : status === 'partial' ? 'yellow' : 'red'
  return (
    <Badge color={color} variant="light" size="sm">
      {status}
    </Badge>
  )
}

function RunDrawer({ run, onClose }: { run: JobRunRow; onClose: () => void }) {
  return (
    <Drawer
      opened
      onClose={onClose}
      title={`Run · ${run.task}`}
      position="right"
      size="md"
      padding="md"
    >
      <Stack gap="md">
        <Section title="When">
          <Text fz="sm">
            {absDateTime(run.startedAt)}{' '}
            <Text component="span" fz="xs" c="dimmed">
              ({relativeTime(run.startedAt)}) · {formatDuration(run.durationMs)}
            </Text>
          </Text>
        </Section>
        <Section title="Status">
          <StatusBadge status={run.status} />
        </Section>
        <Section title="Summary">
          {run.summary ? (
            <Code block style={{ fontSize: 12, whiteSpace: 'pre-wrap' }}>
              {JSON.stringify(run.summary, null, 2)}
            </Code>
          ) : (
            <Text fz="xs" c="dimmed">
              No summary recorded.
            </Text>
          )}
        </Section>
        <Section title="Error">
          {run.error ? (
            <Code block style={{ fontSize: 12, whiteSpace: 'pre-wrap' }}>
              {run.error}
            </Code>
          ) : (
            <Text fz="xs" c="dimmed">
              No error.
            </Text>
          )}
        </Section>
        <Section title="Run id">
          <code style={{ fontSize: 11 }}>{run.id}</code>
        </Section>
      </Stack>
    </Drawer>
  )
}

function summaryPreview(summary: Record<string, unknown> | null): string {
  if (!summary) return '—'
  const parts = Object.entries(summary)
    .slice(0, 4)
    .map(([k, v]) => `${k}=${typeof v === 'object' ? JSON.stringify(v) : String(v)}`)
  const more = Object.keys(summary).length > 4 ? ` (+${Object.keys(summary).length - 4})` : ''
  return parts.join(' · ') + more
}

function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`
  return `${(ms / 1000).toFixed(ms < 10_000 ? 1 : 0)}s`
}

function truncate(s: string, n: number): string {
  return s.length > n ? `${s.slice(0, n - 1)}…` : s
}

